import {
  CONSECUTIVE_HIT_LIMIT,
  GUARD_DAMAGE_SPECIAL_RATIO,
  GUARD_KNOCKBACK_RATIO,
  GUARD_MIN_HEALTH,
  HIT_INVULN_FRAMES,
  KNOCKBACK_FRAMES,
  MAX_METER,
  MAX_ROUNDS,
  METER_ON_HIT,
  METER_ON_HIT_TAKEN,
  ROUND_INTRO_FRAMES,
  ROUND_OVER_FRAMES,
  ROUND_SECONDS,
  ROUNDS_TO_WIN,
  SIMULATION_HZ,
  START_X_P1,
  START_X_P2,
} from '../core/constants';
import { AIController } from '../ai/AIController';
import {
  ASSIST_CPU_ATTACK_FREQUENCY_SCALE,
  P1_ASSIST_HEALTH_MULTIPLIER,
  type CpuDifficulty,
} from '../core/settings';
import type { GameMode } from '../core/session';
import type { PlayerIndex } from '../input/InputManager';
import { emptyAssets, type CharacterAssets } from '../rendering/CharacterAssets';
import { Fighter, NULL_INPUT, type FighterInput } from './Fighter';
import { rectsOverlap, type AttackKind, type MoveData, type Rect } from './types';
import { pilotChargePreparing } from './chargePilot';
import { contactPose, supportsContact, expandedContact, integratedBite, findContact, react, rectContact, sweptRectContact, circleBounds, type ContactPose, type Contact, type BodyRegion } from './partContact';
import { applyAffine } from '../rendering/partRig';
import { impactStop } from './impactTiming';

/** 맞을 때 최소로 밀려나는 거리(px). 넉백이 0인 다단히트(벨로키 왕복 등)도 조금씩 밀린다. */
const MIN_PUSH: Record<string, number> = { light: 40, heavy: 70, special: 100 };
/** 때린 쪽이 따라 들어가는 비율. */
const FOLLOW_RATIO = 0.33;

/** 막았을 때 반동 프레임(파란 방패 불꽃 + '팅'). */
const GUARD_RECOIL_FRAMES = 10;
import type { HitParams, ProjectileSpec, ScriptBox } from './moveScript';

/** 날아가는 그림(골판·물결·충격파). 판정은 Match가, 그림은 BattleScene이 맡는다. */
export interface Projectile {
  owner: PlayerIndex;
  kind: AttackKind;
  x: number;
  y: number;
  vx: number;
  vy: number;
  gravity: number;
  rotation: number;
  spin: number | null;
  life: number;
  /** 나온 뒤 지난 시간(초). 커지기·사라지기 연출용. */
  age: number;
  /** 쏜 기술의 공격 id(소나기 여러 장을 연속 피격 1회로 센다). */
  attackId: number;
  /** 이미 맞혔는지(관통 투사체). */
  spent: boolean;
  readonly spec: ProjectileSpec;
  facing: 1 | -1;
}

export type RoundPhase = 'intro' | 'fight' | 'roundOver' | 'matchOver';

/**
 * 프롬프트 6 연출용 사건. Match는 "무슨 일이 있었는지"만 남기고,
 * 화면(BattleScene)이 이벤트를 소비해 먼지·별·충격파·진동·소리를 낸다.
 * 이벤트는 보이는 연출 전용이라 전투 수치에 영향을 주지 않는다.
 */
export interface MatchEvent {
  /** fx = 기술 스크립트가 낸 화면 연출(흔들림·먼지·충격파·물보라·번쩍). stun = 기절 시작. */
  type: 'hit' | 'guard' | 'ko' | 'fx' | 'stun' | 'special';
  fx?: 'shake' | 'dust' | 'shockwave' | 'splash' | 'flash' | 'slash' | 'feathers';
  strength?: number;
  /** 사건이 일어난 위치(화면 x, 지면 기준 y). */
  x: number;
  y: number;
  direction: 1 | -1;
  kind: AttackKind;
  player: PlayerIndex;
  /** 때린 쪽 종 id(종별 타격 불꽃 색, 특수기 컷인). */
  attackerId?: string;
  region?: BodyRegion;
  part?: string;
}

/** 특수기 컷인 동안 경기를 멈추는 프레임(0.6초). */
export const SPECIAL_CUTIN_FRAMES = 36;

/** 계획서 16절 프롬프트 5: 난이도·도움 설정·테스트용 난수원. */
export interface MatchOptions {
  difficulty?: CpuDifficulty;
  assist?: boolean;
  random?: () => number;
  /** 특수기 컷인 동안 경기를 멈출지(화면에서만 켠다. 규칙 테스트는 끈 채로 프레임을 센다). */
  specialCutin?: boolean;
  /** Opt-in two-species pilot; production/legacy behavior stays unchanged until review. */
  partContacts?: boolean;
  impactTiming?: boolean;
}

interface HitEvent {
  attacker: Fighter;
  defender: Fighter;
  move: MoveData;
  guarded: boolean;
}

/**
 * 한 경기(45초 라운드 · 2라운드 선승)를 진행한다.
 * 계획서 2~3절: 자동 가드, 게이지, 넉백, 피격 경직, 동시 타격 해결 후 KO 판정, 무승부 재라운드.
 */
export class Match {
  readonly fighters: [Fighter, Fighter];

  phase: RoundPhase = 'intro';
  phaseFrames = 0;
  roundNumber = 1;
  timerFrames = ROUND_SECONDS * SIMULATION_HZ;
  roundWinner: PlayerIndex | null = null;
  matchWinner: PlayerIndex | null = null;
  /** 이번 라운드가 무승부였는지(연출 표시용). */
  roundWasDraw = false;
  /** 두 플레이어가 같은 캐릭터인지(계획서 4절: 동일 캐릭터 대전 허용, 2P 보조색). */
  readonly mirrorMatch: boolean;
  /** 고른 CPU 난이도. */
  readonly difficulty: CpuDifficulty;
  /** 도움 설정이 실제로 켜져 있는지(1인 대전에서만 적용). */
  readonly assistActive: boolean;

  private readonly cpu: AIController | null;
  /** 아직 화면이 소비하지 않은 연출 이벤트. */
  private events: MatchEvent[] = [];
  private previousPoses = new Map<Fighter, ContactPose>();
  private previousFacing = new Map<Fighter, number>();
  private contacts = new Map<Fighter, Contact>();
  /** 남은 특수기 컷인 프레임(0이면 없음)과 발동한 쪽. */
  cutinFrames = 0;
  cutinPlayer: PlayerIndex = 0;
  private readonly specialCutin: boolean;
  private readonly impactTiming: boolean;
  /** 지금 날아가는 투사체. */
  projectiles: Projectile[] = [];

  constructor(
    private readonly mode: GameMode,
    characterIds: [string, string],
    assets: [CharacterAssets, CharacterAssets] = [
      emptyAssets(characterIds[0]),
      emptyAssets(characterIds[1]),
    ],
    options: MatchOptions = {},
  ) {
    this.mirrorMatch = characterIds[0] === characterIds[1];
    this.difficulty = options.difficulty ?? 'easy';
    this.specialCutin = options.specialCutin === true;
    this.impactTiming = options.impactTiming === true;
    // 계획서 2절: 도움 설정은 1P 체력 1.5배 + CPU 공격 빈도 감소. 기본값은 꺼짐.
    this.assistActive = this.mode === 'cpu' && options.assist === true;

    this.fighters = [
      new Fighter(0, characterIds[0], START_X_P1, 1, assets[0]),
      new Fighter(1, characterIds[1], START_X_P2, -1, assets[1]),
    ];
    this.fighters[0].opponent = this.fighters[1];
    for (const fighter of this.fighters) fighter.partContacts = options.partContacts === true;
    for (const fighter of this.fighters) fighter.impactTiming = this.impactTiming;
    this.fighters[1].opponent = this.fighters[0];
    // 동일 캐릭터일 때만 2P에 보조색을 적용해 구분한다.
    this.fighters[1].useAlternatePalette = this.mirrorMatch;

    this.cpu =
      this.mode === 'cpu'
        ? new AIController(1, {
            difficulty: this.difficulty,
            attackFrequencyScale: this.assistActive ? ASSIST_CPU_ATTACK_FREQUENCY_SCALE : 1,
            random: options.random,
          })
        : null;

    this.applyAssistHealth();
  }

  /** CPU 컨트롤러(1인 대전에서만 존재). 테스트·디버그용. */
  get cpuController(): AIController | null {
    return this.cpu;
  }

  /** 이번 틱에 쌓인 연출 이벤트를 돌려주고 비운다(화면이 매 프레임 소비). */
  consumeEvents(): MatchEvent[] {
    if (this.events.length === 0) return [];
    const events = this.events;
    this.events = [];
    return events;
  }

  /** 2P가 CPU인 경로에서는 사람 입력 대신 AIController의 Action을 쓴다(프롬프트 5). */
  private inputFor(player: PlayerIndex, input: FighterInput): FighterInput {
    if (this.mode === 'cpu' && player === 1) return this.cpu ?? NULL_INPUT;
    return input;
  }

  /** 도움 설정이 켜져 있으면 1P 최대 체력을 1.5배로 잡는다. */
  private applyAssistHealth(): void {
    if (this.assistActive) {
      this.fighters[0].setMaxHealthMultiplier(P1_ASSIST_HEALTH_MULTIPLIER);
      // 4세 도움 모드: 상단·하단 구분 없이 뒤나 아래만 누르면 다 막는다.
      this.fighters[0].guardAll = true;
    }
  }

  get p1(): Fighter {
    return this.fighters[0];
  }

  get p2(): Fighter {
    return this.fighters[1];
  }

  get timeLeftSeconds(): number {
    return Math.max(0, Math.ceil(this.timerFrames / SIMULATION_HZ));
  }

  step(input: FighterInput, dt: number): void {
    this.phaseFrames += 1;

    switch (this.phase) {
      case 'intro':
        // 등장 포즈: ROUND 로고 동안(첫 라운드만). FIGHT!부터는 기본 자세.
        for (const f of this.fighters) f.entrancePose = this.roundNumber === 1 && this.phaseFrames < 55;
        if (this.phaseFrames >= ROUND_INTRO_FRAMES) {
          for (const f of this.fighters) f.entrancePose = false;
          this.phase = 'fight';
          this.phaseFrames = 0;
        }
        break;

      case 'fight':
        this.contacts.clear();
        this.previousPoses.clear();
        for (const fighter of this.fighters) if (supportsContact(fighter)) {
          this.previousPoses.set(fighter, contactPose(fighter));
          this.previousFacing.set(fighter, fighter.facing);
        }
        // 특수기 컷인: 화면이 어두워지고 초상이 지나가는 동안 경기를 멈춘다.
        if (this.cutinFrames > 0) {
          this.cutinFrames -= 1;
          break;
        }
        // CPU는 이번 틱의 공개 상태를 보고 Action을 정한 뒤, 사람과 같은 경로로 step한다.
        this.cpu?.update(this.p2, this.p1, dt);
        for (const fighter of this.fighters) {
          const wasAttacking = fighter.attack?.attackId;
          fighter.step(this.inputFor(fighter.player, input), dt);
          if (fighter.attack && fighter.attack.attackId !== wasAttacking && fighter.attack.move.kind === 'special') {
            if (this.specialCutin) this.cutinFrames = SPECIAL_CUTIN_FRAMES;
            this.cutinPlayer = fighter.player;
            this.events.push({ type: 'special', x: fighter.x, y: 0, direction: fighter.facing, kind: 'special', player: fighter.player, attackerId: fighter.data.id });
          }
        }
        this.updateHeld();
        this.updateFacing();
        this.separate();
        this.resolveScripts();
        this.updateHeld();
        this.stepProjectiles(dt);
        this.resolveHits();
        this.timerFrames -= 1;
        if (this.checkKnockouts()) break;
        if (this.timerFrames <= 0) this.resolveTimeout();
        break;

      case 'roundOver':
        for (const fighter of this.fighters) fighter.settleAfterRound(dt);
        if (this.phaseFrames >= ROUND_OVER_FRAMES && this.fighters.every(f=>f.onGround)) this.advanceAfterRound();
        break;

      case 'matchOver':
        break;
    }
  }

  // --- 라운드 진행 ---

  private startRound(): void {
    this.phase = 'intro';
    this.phaseFrames = 0;
    this.roundWinner = null;
    this.roundWasDraw = false;
    this.timerFrames = ROUND_SECONDS * SIMULATION_HZ;
    this.applyAssistHealth();
    this.p1.resetForRound(START_X_P1, 1);
    this.p2.resetForRound(START_X_P2, -1);
    this.p2.useAlternatePalette = this.mirrorMatch;
    this.projectiles = [];
    this.cutinFrames = 0;
    // 라운드가 바뀌면 CPU 판단·휴식·특수기 쿨다운도 정확히 초기화한다.
    this.cpu?.reset();
  }

  private endRound(winner: PlayerIndex | null): void {
    this.phase = 'roundOver';
    this.phaseFrames = 0;
    this.roundWinner = winner;
    this.roundWasDraw = winner === null;

    this.projectiles = [];
    for (const fighter of this.fighters) {
      fighter.releaseHold();
      fighter.attack = null;
      fighter.scriptVisual = null;
      fighter.ghosts = [];
      fighter.hitstunFrames = 0;
      fighter.kbFrames = 0;
      fighter.kbPerFrame = 0;
    }

    if (winner === null) {
      // 무승부는 승수를 올리지 않고 재라운드한다(계획서 2절).
      this.p1.finishRound('down');
      this.p2.finishRound('down');
      this.pushKoEvent(this.p1);
      this.pushKoEvent(this.p2);
    } else {
      this.fighters[winner].roundWins += 1;
      this.fighters[winner].finishRound('victory');
      const loser = this.fighters[1 - winner];
      loser.finishRound('down');
      // 프롬프트 6: KO 뒤 쓰러진 캐릭터에 별이 돈다.
      this.pushKoEvent(loser);
    }
  }

  private pushKoEvent(fighter: Fighter): void {
    this.events.push({
      type: 'ko',
      x: fighter.x,
      y: fighter.y - fighter.bodyHeight * 0.4,
      direction: fighter.facing,
      kind: 'heavy',
      player: fighter.player,
    });
  }

  private advanceAfterRound(): void {
    if (this.p1.roundWins >= ROUNDS_TO_WIN) {
      this.matchWinner = 0;
      this.phase = 'matchOver';
      return;
    }
    if (this.p2.roundWins >= ROUNDS_TO_WIN) {
      this.matchWinner = 1;
      this.phase = 'matchOver';
      return;
    }
    if (this.roundNumber >= MAX_ROUNDS) {
      this.matchWinner = null;
      this.phase = 'matchOver';
      return;
    }
    this.roundNumber += 1;
    this.startRound();
  }

  // --- 판정 ---

  private updateFacing(): void {
    const [a, b] = this.fighters;
    if (a.x === b.x) return;
    const free = (f: Fighter): boolean => f.state !== 'attack' && f.state !== 'held';
    if (free(a)) a.facing = a.x < b.x ? 1 : -1;
    if (free(b)) b.facing = b.x < a.x ? 1 : -1;
  }

  /** 몸통이 겹치지 않게 밀어낸다. 상대 몸통을 통과하지 않는다. */
  private separate(): void {
    const [a, b] = this.fighters;
    // 잡기 중이거나 상대를 통과하는 기술(왕복)은 밀어내지 않는다.
    if (a.holding || b.holding || (a.activeScript?.passThrough && !pilotChargePreparing(a)) || (b.activeScript?.passThrough && !pilotChargePreparing(b))) return;
    if (a.isIntangible() || b.isIntangible()) return;
    // 넘어진 상대는 넘어갈 수 있다(쓰러진 위로 지나가기).
    if (a.state === 'fallen' || b.state === 'fallen') return;
    const minGap = (this.pushWidth(a) + this.pushWidth(b)) / 2;
    const gap = Math.abs(a.x - b.x);
    if (gap >= minGap) return;

    const push = (minGap - gap) / 2;
    if (a.x <= b.x) {
      a.x -= push;
      b.x += push;
    } else {
      a.x += push;
      b.x -= push;
    }
    a.clampToArena();
    b.clampToArena();
    // Transfer unresolved separation to the free fighter when the other is against a wall.
    const remaining = supportsContact(a) && supportsContact(b) ? minGap - Math.abs(a.x - b.x) : 0;
    if (remaining > 0.01) {
      const sign = a.x <= b.x ? -1 : 1;
      a.x += sign * remaining; a.clampToArena();
      const rest = minGap - Math.abs(a.x - b.x);
      if (rest > 0) { b.x -= sign * rest; b.clampToArena(); }
    }
  }

  pushWidth(f: Fighter): number { return supportsContact(f) ? f.data.displayHeight * 0.42 : f.bodyWidth; }

  /** AABB candidate rejection only; a part sweep is always required for a pilot hit. */
  private touching(attacker: Fighter, defender: Fighter, legacy: Rect, groundArea = false): boolean {
    if (!supportsContact(attacker) || !supportsContact(defender)) return rectsOverlap(legacy, defender.hurtbox());
    const a = contactPose(attacker), b = contactPose(defender);
    // Quakes are authored ground areas, not foot-to-body strikes. Preserve their range.
    if (groundArea) {
      const contact = rectContact(legacy, b.hurt, attacker.facing);
      if (contact) this.contacts.set(defender, contact);
      return !!contact;
    }
    const previousA = this.previousFacing.get(attacker) === attacker.facing ? this.previousPoses.get(attacker) ?? a : a;
    const previousB = this.previousFacing.get(defender) === defender.facing ? this.previousPoses.get(defender) ?? b : b;
    // Replacement-flight art and instantaneous sx flips aren't continuous swept motion.
    const continuous = (old: ContactPose, now: ContactPose): boolean =>
      old.hurt.length === now.hurt.length && old.hurt[0]?.part === now.hurt[0]?.part &&
      Math.sign(old.stage[0]*old.stage[3]-old.stage[1]*old.stage[2]) === Math.sign(now.stage[0]*now.stage[3]-now.stage[1]*now.stage[2]);
    const oldA = continuous(previousA,a) && previousA.weapon.length===a.weapon.length ? previousA : a;
    const oldB = continuous(previousB,b) ? previousB : b;
    if (!rectsOverlap(circleBounds([...a.weapon, ...oldA.weapon]), circleBounds([...b.hurt, ...oldB.hurt]))) return false;
    const contact = integratedBite(attacker)
      ? findContact(a.weapon, b.hurt, a.weapon, b.hurt, attacker.facing)
      : findContact(a.weapon, b.hurt, oldA.weapon, oldB.hurt, attacker.facing);
    if (!contact) return false;
    this.contacts.set(defender, contact);
    return true;
  }

  /** 동일 틱의 양쪽 타격을 모아 함께 해결한다(계획서 16절 프롬프트 2). */
  private resolveHits(): void {
    const events: HitEvent[] = [];

    for (const attacker of this.fighters) {
      if (attacker.state !== 'attack' || !attacker.attack) continue;
      const defender = this.opponentOf(attacker);
      if (attacker.attack.hitTargets.has(defender.player)) continue;
      if (defender.invulnFrames > 0) continue;
      if (defender.state === 'down' || defender.state === 'victory') continue;
      if (defender.state === 'held' || defender.state === 'fallen') continue;
      if (defender.isIntangible()) continue;

      const hitboxes = attacker.activeHitboxes();
      if (hitboxes.length === 0) continue;
      const hurtbox = defender.hurtbox();
      if (!hitboxes.some((box) => supportsContact(attacker) && supportsContact(defender)
        ? this.touching(attacker, defender, box) : rectsOverlap(box, hurtbox))) continue;

      attacker.attack.hitTargets.add(defender.player);
      events.push({
        attacker,
        defender,
        move: attacker.attack.move,
        guarded: defender.isGuarding(attacker),
      });
    }

    for (const event of events) this.applyHit(event);
  }

  /** 맞는 쪽이 반격 자세면 피해 없이 반격으로 넘어간다(안킬로 철벽 반격). */
  private counterHit(attacker: Fighter, defender: Fighter): boolean {
    if (!defender.tryCounter()) return false;
    attacker.hitstopFrames = 10;
    defender.hitstopFrames = 10;
    // 반격이 맞는 방향을 보도록 돌려 세운다.
    this.pushFx(defender, 'flash', 1.5);
    this.events.push({ type: 'guard', x: (attacker.x + defender.x) / 2, y: defender.y - defender.bodyHeight * 0.55, direction: defender.facing, kind: 'special', player: defender.player });
    return true;
  }

  private applyHit({ attacker, defender, move, guarded }: HitEvent): void {
    const direction: 1 | -1 = defender.x >= attacker.x ? 1 : -1;
    if (this.counterHit(attacker, defender)) return;

    if (!guarded) defender.startImpactRecoil(move.kind, direction);

    let damage = move.damage * attacker.data.damageScale;
    if (guarded) {
      damage *= move.kind === 'special' ? GUARD_DAMAGE_SPECIAL_RATIO : 0;
    }
    damage = Math.round(damage);

    if (guarded) {
      // 가드: 약·강 피해 0, 특수기 20%. 체력은 1 아래로 내려가지 않는다.
      defender.health = Math.max(GUARD_MIN_HEALTH, defender.health - damage);
      defender.kbPerFrame = (direction * move.knockback * GUARD_KNOCKBACK_RATIO) / KNOCKBACK_FRAMES;
      defender.kbFrames = KNOCKBACK_FRAMES;
      defender.guardRecoil(GUARD_RECOIL_FRAMES);
    } else {
      defender.health = Math.max(0, defender.health - damage);
      defender.releaseHold();
      defender.state = 'hit';
      defender.hitstunFrames = move.hitstunFrames;
      defender.attack = null;
      defender.scriptVisual = null;
      defender.kbPerFrame = (direction * move.knockback) / KNOCKBACK_FRAMES;
      defender.kbFrames = KNOCKBACK_FRAMES;

      attacker.meter = Math.min(MAX_METER, attacker.meter + METER_ON_HIT);
      defender.meter = Math.min(MAX_METER, defender.meter + METER_ON_HIT_TAKEN);
      attacker.consecutiveHits = 0;

      defender.consecutiveHits += 1;
      if (defender.consecutiveHits >= CONSECUTIVE_HIT_LIMIT) {
        defender.invulnFrames = HIT_INVULN_FRAMES;
        defender.consecutiveHits = 0;
      }
    }

    // 타격 정지는 양측에 동일 적용한다.
    const stop = this.impactTiming
      ? impactStop(attacker.data.id, move.kind, move.hitstopFrames, guarded, false)
      : move.hitstopFrames;
    attacker.hitstopFrames = stop;
    defender.hitstopFrames = stop;

    // 연출용 이벤트(피해와 무관). 맞은 지점은 두 몸통 사이, 가슴 높이로 잡는다.
    this.events.push({
      type: guarded ? 'guard' : 'hit',
      x: (attacker.x + defender.x) / 2,
      y: defender.y - defender.bodyHeight * 0.55,
      direction,
      kind: move.kind,
      player: defender.player,
    });
  }

  // --- 기술 스크립트(잡기·다단히트·투사체·던지기·위치 바꾸기) ---

  /** 잡힌 쪽을 잡은 쪽 입 앞(스크립트 hold 키)에 붙인다. */
  private updateHeld(): void {
    for (const holder of this.fighters) {
      const target = holder.holding;
      if (!target) continue;
      if (holder.state !== 'attack') {
        holder.releaseHold();
        continue;
      }
      const hold = holder.holdOffset();
      if (integratedBite(holder) && target.biteAnchor) {
        const anchor = target.biteAnchor;
        const mouth = contactPose(holder).mouth;
        const m = contactPose(target).matrices[anchor.part];
        const [x, y] = applyAffine(m, anchor.x, anchor.y);
        // Preserve the captured point's offset: no snap on acquisition, no center/radius re-fit.
        target.x += mouth.x + anchor.dx - x;
        target.y += mouth.y + anchor.dy - y;
        target.onGround = target.y >= 0;
        target.vy = 0;
        continue;
      }
      if (supportsContact(holder) && supportsContact(target) && !expandedContact(holder)) {
        // Carry from the actual jaw/horn, not the master silhouette's front edge.
        target.heldRot = hold.rot;
        const weapon = contactPose(holder).weapon[0];
        const regions = contactPose(target).hurt;
        const anchor = regions.find(c => c.part === target.lastContact?.part) ?? regions[0];
        const dx = weapon.x - anchor.x, dy = weapon.y - anchor.y;
        const length = Math.hypot(dx, dy) || 1;
        target.x += dx - dx / length * anchor.r;
        target.y = Math.min(0, target.y + dy - dy / length * anchor.r);
        target.onGround = target.y >= 0;
        target.vy = 0;
        continue;
      }
      target.x = holder.x + holder.facing * (holder.bodyFront + hold.x);
      target.y = Math.min(0, holder.y + hold.y);
      target.onGround = target.y >= 0;
      target.vy = 0;
      target.facing = (-holder.facing) as 1 | -1;
      target.heldRot = hold.rot;
    }
  }

  private scriptBoxRect(fighter: Fighter, box: ScriptBox): Rect {
    const origin = box.anchor === 'center' ? 0 : fighter.bodyFront;
    const near = origin + box.x;
    const left = fighter.facing === 1 ? fighter.x + near : fighter.x - near - box.w;
    const top = fighter.y + box.y;
    return { left, right: left + box.w, top, bottom: top + box.h };
  }

  /** 디버그 표시용: 지금 프레임에 켜진 스크립트 판정 상자. */
  scriptHitboxes(fighter: Fighter): Rect[] {
    const script = fighter.activeScript;
    const frame = fighter.attack?.frame ?? -1;
    if (!script) return [];
    const boxes: Rect[] = [];
    for (const hit of script.hits ?? []) {
      if (hit.box && frame >= hit.from && frame <= hit.to) boxes.push(this.scriptBoxRect(fighter, hit.box));
    }
    const grab = script.grab;
    if (grab && frame >= grab.from && frame <= grab.to) boxes.push(this.scriptBoxRect(fighter, grab.box));
    return boxes;
  }

  private canBeTouched(defender: Fighter, otg = false): boolean {
    return (
      defender.invulnFrames <= 0 &&
      !defender.isIntangible() &&
      defender.state !== 'down' &&
      defender.state !== 'victory' &&
      (otg || defender.state !== 'fallen')
    );
  }

  private resolveScripts(): void {
    for (const attacker of this.fighters) {
      const attack = attacker.attack;
      const script = attacker.activeScript;
      const run = attack?.script;
      if (!attack || !script || !run) continue;
      if (attacker.hitstopFrames > 0) continue;
      const defender = this.opponentOf(attacker);
      const f = attack.frame;

      // 잡기: 구간 안에 닿으면 붙잡고 성공 경로로, 끝까지 못 잡으면 헛방 경로로.
      const grab = script.grab;
      if (grab && !run.grabResolved && f >= grab.from && f <= grab.to) {
        const touch =
          this.canBeTouched(defender) &&
          defender.state !== 'held' &&
          this.touching(attacker, defender, this.scriptBoxRect(attacker, grab.box));
        if (touch) {
          if (supportsContact(defender)) defender.lastContact = this.contacts.get(defender) ?? null;
          run.grabResolved = true;
          run.grabbed = true;
          defender.releaseHold();
          defender.attack = null;
          defender.scriptVisual = null;
          defender.state = 'held';
          defender.heldBy = attacker;
          if (integratedBite(attacker)) {
            const c = this.contacts.get(defender)!;
            const pose = contactPose(defender), m = pose.matrices[c.part];
            const dx = c.x - m[4], dy = c.y - m[5], det = m[0] * m[3] - m[1] * m[2];
            const mouth = contactPose(attacker).mouth;
            defender.biteAnchor = { part: c.part, x: (m[3] * dx - m[2] * dy) / det,
              y: (-m[1] * dx + m[0] * dy) / det, dx: c.x - mouth.x, dy: c.y - mouth.y };
          }
          attacker.holding = defender;
          if (grab.success !== undefined && !integratedBite(attacker)) attack.frame = grab.success;
          attacker.applyScriptFrame();
          this.updateHeld();
          this.pushFx(attacker, 'dust', 1);
          continue;
        }
        if (f === grab.to) {
          run.grabResolved = true;
          attack.frame = grab.miss;
          attacker.applyScriptFrame();
          continue;
        }
      }

      // 다단히트: 판정마다 한 번씩.
      (script.hits ?? []).forEach((hit, index) => {
        if (run.landed.has(index) || f < hit.from || f > hit.to) return;
        if (hit.target === 'held') {
          if (attacker.holding === defender) {
            if (supportsContact(attacker) && defender.lastContact) {
              const weapon = contactPose(attacker).weapon[0];
              this.contacts.set(defender, { ...defender.lastContact, x: weapon.x, y: weapon.y, direction: attacker.facing });
            }
            run.landed.add(index);
            this.applyDamage(attacker, defender, hit, attack.move.kind, false, attacker.facing, true);
          }
          return;
        }
        if (!hit.box || !this.canBeTouched(defender, hit.otg) || defender.state === 'held') return;
        if (hit.groundOnly && !defender.onGround) return;
        if (!this.touching(attacker, defender, this.scriptBoxRect(attacker, hit.box), !!hit.groundOnly)) return;
        run.landed.add(index);
        const guarded = !hit.unguardable && defender.isGuarding(attacker, hit.level ?? 'mid');
        // 밀려나는 방향은 '공격자에게서 멀어지는 쪽'(뒤돌아 꼬리로 칠 때도 맞다).
        const away: 1 | -1 = this.contacts.get(defender)?.direction ?? (defender.x >= attacker.x ? 1 : -1);
        this.applyDamage(attacker, defender, hit, attack.move.kind, guarded, away, false);
      });

      // 사건: 해당 프레임에 한 번.
      (script.events ?? []).forEach((event, index) => {
        if (event.f !== f || run.fired.has(index)) return;
        run.fired.add(index);
        switch (event.type) {
          case 'projectile':
            this.projectiles.push({
              owner: attacker.player,
              kind: attack.move.kind,
              // 방향은 기술 시작 방향 기준(뒤돌아 꼬리 휘두르는 중에도 상대 쪽으로 쏜다).
              x:
                event.at === 'opponent'
                  ? defender.x + run.startFacing * event.x
                  : attacker.x + run.startFacing * (attacker.bodyFront + event.x),
              y: event.at === 'opponent' ? event.y : attacker.y + event.y,
              vx: run.startFacing * event.vx,
              vy: event.vy ?? 0,
              gravity: event.gravity ?? 0,
              rotation: 0,
              spin: event.spin ?? null,
              life: event.life,
              age: 0,
              attackId: attack.attackId,
              spent: false,
              spec: event,
              facing: run.startFacing,
            });
            if (supportsContact(attacker) && !expandedContact(attacker) && event.at !== 'opponent') {
              const mouth = contactPose(attacker).weapon[0];
              const projectile = this.projectiles[this.projectiles.length - 1];
              projectile.x = mouth.x; projectile.y = mouth.y;
            }
            break;
          case 'throw': {
            const target = attacker.holding;
            if (!target) break;
            if (supportsContact(attacker) && target.lastContact) {
              const weapon = contactPose(attacker).weapon[0];
              this.contacts.set(target, { ...target.lastContact, x: weapon.x, y: weapon.y });
            }
            attacker.releaseHold();
            if (event.behind && !supportsContact(attacker)) {
              target.x = attacker.x - attacker.facing * (attacker.bodyWidth * 0.5);
            }
            const dir = event.behind ? -attacker.facing : attacker.facing;
            target.health = Math.max(0, target.health - Math.round(event.damage * attacker.data.damageScale));
            target.launch(dir * event.vx, event.vy, event.knockdown);
            attacker.meter = Math.min(MAX_METER, attacker.meter + METER_ON_HIT);
            this.pushHitEvent(attacker, target, attack.move.kind, false, dir as 1 | -1);
            break;
          }
          case 'swap': {
            const ax = attacker.x;
            attacker.x = defender.x;
            defender.x = ax;
            break;
          }
          case 'fx':
            this.pushFx(attacker, event.fx, event.strength ?? 1, event.x, event.y);
            break;
          case 'end':
            attacker.endAttack();
            break;
        }
      });
    }
  }

  private pushFx(
    fighter: Fighter,
    fx: NonNullable<MatchEvent['fx']>,
    strength: number,
    x = 0,
    y = 0,
  ): void {
    this.events.push({
      type: 'fx',
      fx,
      strength,
      x: fighter.x + fighter.facing * (fighter.bodyFront + x),
      y: fighter.y + y,
      direction: fighter.facing,
      kind: fighter.attack?.move.kind ?? 'heavy',
      player: fighter.player,
    });
  }

  private stepProjectiles(dt: number): void {
    const alive: Projectile[] = [];
    for (const p of this.projectiles) {
      const previousX = p.x, previousY = p.y;
      p.life -= dt;
      p.vy += p.gravity * dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.rotation = p.spin === null ? Math.atan2(p.vy, Math.abs(p.vx)) : p.rotation + p.spin * dt;
      p.age += dt;
      if (p.life <= 0 || p.x < -400 || p.x > 2320 || p.y > 0) {
        if (p.y > 0) this.events.push({ type: 'fx', fx: 'dust', strength: 0.8, x: p.x, y: 0, direction: p.facing, kind: p.kind, player: p.owner });
        continue;
      }
      const target = this.fighters[1 - p.owner];
      const owner = this.fighters[p.owner];
      const grow = 1 + (p.spec.grow ?? 0) * p.age;
      const box: Rect = {
        left: p.x - (p.spec.w * grow) / 2,
        right: p.x + (p.spec.w * grow) / 2,
        top: p.y - (p.spec.h * grow) / 2,
        bottom: p.y + (p.spec.h * grow) / 2,
      };
      const regions = supportsContact(target) ? contactPose(target).hurt : null;
      const projectileContact = regions ? sweptRectContact({
        left: box.left + previousX - p.x, right: box.right + previousX - p.x,
        top: box.top + previousY - p.y, bottom: box.bottom + previousY - p.y,
      }, box, regions, this.previousPoses.get(target)?.hurt ?? regions, p.facing) : null;
      if (
        !p.spec.harmless &&
        !p.spent &&
        this.canBeTouched(target, p.spec.otg) &&
        target.state !== 'held' &&
        !(p.spec.groundOnly && !target.onGround) &&
        (regions ? !!projectileContact : rectsOverlap(box, target.hurtbox()))
      ) {
        if (projectileContact) this.contacts.set(target, projectileContact);
        const guarded = !p.spec.unguardable && target.isGuarding(owner, p.spec.level ?? 'mid');
        this.applyDamage(owner, target, p.spec, p.kind, guarded, p.facing, false, p.x, p.attackId);
        if (!p.spec.pierce) continue;
        p.spent = true;
      }
      alive.push(p);
    }
    this.projectiles = alive;
  }

  /**
   * 피해·경직·넉백·띄우기·넘어뜨리기·기절 공통 처리(스크립트·투사체).
   * held=true면 잡힌 채로 맞는 타격이라 경직·넉백 없이 피해와 멈칫만 준다.
   */
  private applyDamage(
    attacker: Fighter,
    defender: Fighter,
    hit: HitParams,
    moveKind: AttackKind,
    guarded: boolean,
    direction: 1 | -1,
    held: boolean,
    atX?: number,
    sourceAttackId?: number,
  ): void {
    if (!held && this.counterHit(attacker, defender)) return;
    if (!guarded && !held) defender.startImpactRecoil(moveKind, direction);
    if(this.impactTiming) hit={...hit,hitstop:impactStop(attacker.data.id,moveKind,hit.hitstop,guarded,held)};
    const contact = this.contacts.get(defender);
    if (contact && !guarded && supportsContact(defender)) {
      react(defender, contact);
      // Freeze the first recoil pose on the damage frame, not the untouched pose.
      if(this.impactTiming&&!held){
        const spring=defender.reaction[contact.region];
        const amount=moveKind==='light'?1:2;
        spring.value=Math.max(-3,Math.min(3,spring.value-contact.direction*defender.facing*amount));
      }
    }
    let damage = hit.damage * attacker.data.damageScale;
    if (guarded) damage *= moveKind === 'special' ? GUARD_DAMAGE_SPECIAL_RATIO : 0;
    damage = Math.round(damage);

    if (defender.state === 'fallen') {
      // 넘어진 상대를 덮치기(otg): 넘어진 채로 피해와 멈칫만 받는다.
      defender.health = Math.max(0, defender.health - damage);
      defender.fallenFrames = Math.max(defender.fallenFrames, 24);
      attacker.hitstopFrames = hit.hitstop;
      defender.hitstopFrames = hit.hitstop;
      this.pushHitEvent(attacker, defender, hit.fx ?? moveKind, false, direction, atX);
      return;
    }
    if (guarded) {
      defender.health = Math.max(GUARD_MIN_HEALTH, defender.health - damage);
      defender.kbPerFrame = (direction * Math.max(hit.knockback, 60) * GUARD_KNOCKBACK_RATIO) / KNOCKBACK_FRAMES;
      defender.kbFrames = KNOCKBACK_FRAMES;
      defender.guardRecoil(GUARD_RECOIL_FRAMES);
    } else {
      defender.health = Math.max(0, defender.health - damage);
      attacker.meter = Math.min(MAX_METER, attacker.meter + METER_ON_HIT);
      defender.meter = Math.min(MAX_METER, defender.meter + METER_ON_HIT_TAKEN);
      if (!held) {
        defender.releaseHold();
        defender.attack = null;
        defender.scriptVisual = null;
        if (hit.launch) {
          defender.launch(direction * hit.launch.vx, hit.launch.vy, hit.knockdown ?? 0);
        } else if (hit.knockdown) {
          defender.knockDown(hit.knockdown);
        } else if (hit.stun) {
          defender.stun(hit.stun);
          this.events.push({ type: 'stun', x: defender.x, y: defender.y - defender.bodyHeight, direction, kind: moveKind, player: defender.player });
        } else {
          defender.state = 'hit';
          defender.hitstunFrames = hit.hitstun;
        }
        // '벽에 대고 치는 느낌' 없애기(jk 2026-10-02): 맞으면 최소한 이만큼은 밀려나고,
        // 때린 쪽은 그 1/3만큼 따라 들어간다(맞는 순간 몸이 서로 붙어 있는 것처럼 보이지 않게).
        const push = Math.max(hit.knockback, MIN_PUSH[hit.fx ?? moveKind] ?? 40);
        defender.kbPerFrame = (direction * push) / KNOCKBACK_FRAMES;
        defender.kbFrames = hit.launch ? 0 : KNOCKBACK_FRAMES;
        if (!supportsContact(attacker) && !hit.launch && !attacker.holding && attacker.onGround) {
          const follow = direction * push * FOLLOW_RATIO;
          // 스크립트 기술은 위치를 시작점 기준으로 다시 계산하므로 시작점을 옮겨 따라 들어가게 한다.
          if (attacker.attack?.script) attacker.attack.script.startX += follow;
          else if (attacker.kbFrames <= 0) {
            attacker.kbPerFrame = follow / KNOCKBACK_FRAMES;
            attacker.kbFrames = KNOCKBACK_FRAMES;
          }
        }
      }
      // 다단히트 기술은 한 기술을 '연속 피격 1회'로 센다(왕복 5연타가 보호 무적에 끊기지 않게).
      const attackId = sourceAttackId ?? attacker.attack?.attackId ?? -1;
      if (defender.lastCountedAttackId !== attackId || attackId === -1) {
        defender.lastCountedAttackId = attackId;
        attacker.consecutiveHits = 0;
        defender.consecutiveHits += 1;
        if (defender.consecutiveHits >= CONSECUTIVE_HIT_LIMIT && !held) {
          defender.invulnFrames = HIT_INVULN_FRAMES;
          defender.consecutiveHits = 0;
        }
      }
    }

    attacker.hitstopFrames = hit.hitstop;
    defender.hitstopFrames = hit.hitstop;
    this.pushHitEvent(attacker, defender, hit.fx ?? moveKind, guarded, direction, atX);
  }

  private pushHitEvent(
    attacker: Fighter,
    defender: Fighter,
    kind: AttackKind,
    guarded: boolean,
    direction: 1 | -1,
    atX?: number,
  ): void {
    const contact = this.contacts.get(defender);
    this.events.push({
      type: guarded ? 'guard' : 'hit',
      x: contact?.x ?? atX ?? (attacker.x + defender.x) / 2,
      y: contact?.y ?? defender.y - defender.bodyHeight * 0.55,
      region: contact?.region,
      part: contact?.part,
      direction,
      kind,
      player: defender.player,
      attackerId: attacker.data.id,
    });
  }

  private checkKnockouts(): boolean {
    const fallen = this.fighters.filter((fighter) => fighter.health <= 0);
    if (fallen.length === 0) return false;
    if (fallen.length === 2) {
      this.endRound(null);
    } else {
      this.endRound(fallen[0].player === 0 ? 1 : 0);
    }
    return true;
  }

  /** 계획서 2절: 시간 종료 시 절대 체력이 아닌 남은 체력 비율을 비교한다. */
  private resolveTimeout(): void {
    // 도움 설정으로 최대 체력이 달라져도 공정하게 비교한다.
    const ratioP1 = this.p1.health / this.p1.maxHealth;
    const ratioP2 = this.p2.health / this.p2.maxHealth;
    if (Math.abs(ratioP1 - ratioP2) < 1e-6) {
      this.endRound(null);
    } else {
      this.endRound(ratioP1 > ratioP2 ? 0 : 1);
    }
  }

  private opponentOf(fighter: Fighter): Fighter {
    return fighter.player === 0 ? this.p2 : this.p1;
  }
}
